  "dm.step.departments.title": "1. Departments",
  "dm.step.departments.help": "Every employee needs a department, and a department needs a code — the system will not invent one from the name.",
  "dm.sheet.departments": "Departments",
  "dm.step.employees.title": "2. Employees",
  "dm.step.employees.help": "Salaries are not in this file — they go on the employment contract later.",
  "dm.sheet.employees": "Employees",
  "dm.step.treasury-accounts.title": "3. Treasury accounts",
  "dm.step.treasury-accounts.help": "An opening balance here posts a real journal entry — check the total on the review screen before you confirm.",
  "dm.sheet.treasury-accounts": "Treasury accounts",
  "dm.step.suppliers.title": "4. Suppliers",
  "dm.step.suppliers.help": "Before items, because an item can point at a preferred supplier. Outstanding balances are not in this file — they are recorded later.",
  "dm.sheet.suppliers": "Suppliers",
  "dm.step.customers.title": "5. Customers",
  "dm.step.customers.help": "Independent of the other steps — customer balances are not recorded here; they are derived later from the historical sales invoices you import.",
  "dm.sheet.customers": "Customers",
  "dm.step.items.title": "6. Items",
  "dm.step.items.help": "After suppliers, because an item points at a preferred supplier. Categories and brands are created automatically if they do not exist.",
  "dm.sheet.items": "Items",
  "dm.step.item-units.title": "7. Item units",
  "dm.step.item-units.help": "After items, because every row refers to an item by code — this covers secondary units (carton, dozen) with a conversion factor for each.",
  "dm.sheet.item-units": "Item units",
  "dm.step.asset-categories.title": "8. Asset categories",
  "dm.step.asset-categories.help": "Before fixed assets, because the category sets the default asset and depreciation accounts.",
  "dm.sheet.asset-categories": "Asset categories",
  "dm.step.assets.title": "9. Fixed assets",
  "dm.step.assets.help": "After asset categories — these are recorded as an opening balance, with no new journal entry.",
  "dm.sheet.assets": "Fixed assets",
  "dm.step.historical-sales-invoices.title": "10. Historical sales invoices",
  "dm.step.historical-sales-invoices.help": "Last in order, because every invoice refers to a customer and to items that must already exist. A fully paid invoice is archived with no journal entry, and anything outstanding is recorded only as customer debt — stock is never touched.",
  "dm.sheet.historical-sales-invoices": "Historical sales invoices",
  "dm.step.historical-sales-returns.title": "11. Historical sales returns",
  "dm.step.historical-sales-returns.help": "Import the invoices first — a return must attach to an imported invoice. Stock is not touched.",
  "dm.sheet.historical-sales-returns": "Historical sales returns",
  "dm.step.historical-purchase-invoices.title": "12. Historical purchase invoices",
  "dm.step.historical-purchase-invoices.help": "The purchases-side counterpart of historical sales invoices — it refers to suppliers and items. Stock is not touched.",
  "dm.sheet.historical-purchase-invoices": "Historical purchase invoices",
  "dm.step.historical-purchase-returns.title": "13. Historical purchase returns",
  "dm.step.historical-purchase-returns.help": "The counterpart of historical sales returns — import the invoices first. Stock is not touched.",
  "dm.sheet.historical-purchase-returns": "Historical purchase returns",

